class GSLMatrix(ctypes.Structure):
    _fields_ = ["data", "size1", "size2", "tda"]

def create_gsl_matrix(np_array):
    # Assuming np_array is a 2D numpy array
    size1 = np_array.shape[0]
    size2 = np_array.shape[1]
    data_type = ctypes.c_double * (size1 * size2)
    data = data_type(*np_array.flatten())
    tda = size2
    return GSLMatrix(data, size1, size2, tda)

def copy_matrix(dest, src):
    if dest.size1 != src.size1 or dest.size2 != src.size2:
        return -1  # Matrices must have the same dimensions
    gsl.gsl_matrix_memcpy.argtypes = [ctypes.POINTER(GSLMatrix), ctypes.POINTER(GSLMatrix)]
    gsl.gsl_matrix_memcpy.restype = ctypes.c_int
    return gsl.gsl_matrix_memcpy(ctypes.byref(dest), ctypes.byref(src))

