ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLFunction:
    def __init__(self, func):
        self.func = func

        @staticmethod
def wrapper(x, params):
            return params.func(x)

        self.wrapper_func = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.POINTER(ctypes.c_void_p))(
            wrapper,
        )

        self.params = ctypes.c_void_p()

    def integrate_with_singularity(self, a, b, c):
        func_ptr = ctypes.cast(self.wrapper_func, ctypes.c_void_p)
        params_ptr = ctypes.pointer(ctypes.byref(self.params))
        result = ctypes.c_double(0.0)
        abserr = ctypes.c_double(0.0)
        flag = ctypes.c_int(0)

        gsl.gsl_integration_qc25c(
            func_ptr,
            a,
            b,
            c,
            params_ptr,
            ctypes.byref(result),
            ctypes.byref(abserr),
            ctypes.byref(flag),
        )

        return (result.value, abserr.value, flag.value)

