def create_gsl_matrix_complex(np_array):
    rows, cols = np_array.shape
    data_ptr = np_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    gsl_mat = gsl.gsl_matrix_complex(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl.gsl_matrix_complex_set(gsl_mat, i, j, data_ptr[i*cols + 2*j], data_ptr[i*cols + 2*j + 1])
    return gsl_mat

def complex_qr_decomp(A, T):
    rows = A.shape[0]
    cols = A.shape[1]
    if rows != cols:
        return -1

    A_gsl = create_gsl_matrix_complex(A)
    T_gsl = create_gsl_matrix_complex(T)

    status = gsl.gsl_linalg_complex_QR_decomp_r(A_gsl, T_gsl)

    if status != 0:
        return status

    for i in range(rows):
        for j in range(cols):
            A[i, j] = complex(gsl.gsl_matrix_complex_get_real(A_gsl, i, j), gsl.gsl_matrix_complex_get_imag(A_gsl, i, j))

    return 0

