def copy_matrix(source, destination):
    c_source = (ctypes.c_double * 16)()
    for i in range(4):
        for j in range(4):
            c_source[i*4 + j] = source[i][j]

    c_destination = (ctypes.c_double * 16)()
    for i in range(4):
        for j in range(4):
            c_destination[i*4 + j] = destination[i][j]

    gsl.copy_matrix_gsl(c_source, c_destination)

