class gsl_matrix_complex(ctypes.Structure):
    _fields_ = ["data", "tda", "size1", "size2"]

class gsl_vector(ctypes.Structure):
    _fields_ = ["data", "stride", "size"]

class gsl_eigen_hermv_workspace(ctypes.Structure):
    pass

gsl_complex = ctypes.c_double * 2

def compute_eigen(matrix, size):
    matrix_ptr = (gsl_matrix_complex * size)()\    vector_ptr = (gsl_vector * size)()\    workspace_ptr = gsl_eigen_hermv_workspace(size)
    eigenvalues_ptr = (gsl_complex * size)()
    eigenvectors_ptr = (gsl_matrix_complex * size)()

    for i in range(size):
        for j in range(size):
            matrix_ptr[i].data[j] = ctypes.c_double(matrix[i][j].real)
            matrix_ptr[i].data[j + 1] = ctypes.c_double(matrix[i][j].imag)

    gsl.gsl_eigen_hermv(matrix_ptr, vector_ptr, workspace_ptr)
    for i in range(size):
        eigenvalues_ptr[i] = matrix_ptr[i].data[2 * i]
        eigenvectors_ptr[i].data = (ctypes.c_double * (size * 2))(*matrix_ptr[i].data[:size*2])

    return [eigenvalue for eigenvalue in eigenvalues_ptr], [[complex(eigenvector[2 * j], eigenvector[2 * j + 1]) for j in range(size)] for eigenvector in eigenvectors_ptr]

