class GSLSpMatrix:
    def __init__(self, size):
        self.matrix = gsl.gsl_spmatrix_alloc(size, size)

    def create_sparse_matrix(self, size):
        return gsl.gsl_spmatrix_alloc(size, size)

    def set_sparse_matrix_element(self, row, col, value):
        gsl.gsl_spmatrix_set(self.matrix, row, col, value)

    def get_sparse_matrix_elements(self):
        result = []
        for i in range(gsl.gsl_spmatrix_size1(self.matrix)):
            for j in range(gsl.gsl_spmatrix_size2(self.matrix)):
                if gsl.gsl_spmatrix_get(self.matrix, i, j) != 0.0:
                    result.append((i, j, gsl.gsl_spmatrix_get(self.matrix, i, j)))
        return result

    def swap_sparse_matrix_elements(self, i, j):
        val_i = gsl.gsl_spmatrix_get(self.matrix, i, j)
        for k in range(gsl.gsl_spmatrix_size1(self.matrix)):
            for l in range(gsl.gsl_spmatrix_size2(self.matrix)):
                if gsl.gsl_spmatrix_get(self.matrix, k, l) != 0.0 and (k, l) != (i, j):
                    temp = gsl.gsl_spmatrix_get(self.matrix, k, l)
                    gsl.gsl_spmatrix_set(self.matrix, k, l, val_i)
                    gsl.gsl_spmatrix_set(self.matrix, i, j, temp)
                    return

