    matrix.set_sparse_matrix_element(0, 1, 5.0)
    matrix.set_sparse_matrix_element(1, 2, 10.0)
    print("Before swap:", matrix.get_sparse_matrix_elements())
    matrix.swap_sparse_matrix_elements(0, 1)
    print("After swap:", matrix.get_sparse_matrix_elements())

