import ctypes

gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")


class gsl_matrix(ctypes.Structure):
    _fields_ = ["data", "tda", "size1", "size2"]

class gsl_vector(ctypes.Structure):
    _fields_ = ["data", "stride", "size"]

def matrix_to_gsl(matrix):
    M, N = len(matrix), len(matrix[0])
    data = (ctypes.c_double * (M*N))()
    for i in range(M):
        for j in range(N):
            data[i*N + j] = matrix[i][j]
    return gsl_matrix(data=data, tda=N, size1=M, size2=N)

def vector_to_gsl(vector):
    N = len(vector)
    data = (ctypes.c_double * N)()
    for i in range(N):
        data[i] = vector[i]
    return gsl_vector(data=data, stride=1, size=N)

def gsl_matrix_to_list(matrix):
    M = matrix.size1
    result = [[0.0]*matrix.size2 for _ in range(M)]
    for i in range(M):
        for j in range(matrix.tda):
            result[i][j] = matrix.data[i*matrix.tda + j]
    return result

def gsl_vector_to_list(vector):
    N = vector.size
    result = [0.0]*N
    for i in range(N):
        result[i] = vector.data[i]
    return result

def ql_decomposition_and_unpack(A, tau):
    M, N = len(A), len(A[0])
    A_gsl = matrix_to_gsl(A)
    tau_gsl = vector_to_gsl(tau)

    gsl.gsl_linalg_QL_decomp.argtypes = [ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_vector)]
    gsl.gsl_linalg_QL_decomp.restype = None

    gsl.gsl_linalg_QL_unpack.argtypes = [ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_vector), ctypes.POINTER(gsl_matrix), ctypes.POINTER(gsl_matrix)]
    gsl.gsl_linalg_QL_unpack.restype = None

    Q = gsl_matrix()
    L = gsl_matrix()

    gsl.gsl_linalg_QL_decomp(ctypes.byref(A_gsl), ctypes.byref(tau_gsl))
    gsl.gsl_linalg_QL_unpack(ctypes.byref(A_gsl), ctypes.byref(tau_gsl), ctypes.byref(Q), ctypes.byref(L))

    Q_list = gsl_matrix_to_list(Q)
    L_list = gsl_matrix_to_list(L)

    return Q_list, L_list

