class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix
        self.n = len(matrix)
        self.data = (ctypes.c_double * (self.n ** 2))()
        for i in range(self.n):
            for j in range(self.n):
                self.data[i * self.n + j] = matrix[i][j]

    def is_positive_definite(self):
        return all(self.data[i * self.n + i] > 0 for i in range(self.n))

    def cholesky_decomp(self):
        if not self.is_positive_definite():
            raise ValueError("Matrix must be positive definite")
        gsl.gsl_linalg_cholesky_decomp(ctypes.byref(self.data), ctypes.c_size_t(self.n))
        return [[self.data[i * self.n + j] for j in range(i + 1)] for i in range(self.n)]

