class gsl_function(ctypes.Structure):
    _fields_ = ["function", "params"]

def compute_integral(py_func, a, b, epsabs, epsrel, n):
    def func_wrapper(x, params):
        return py_func(x)
    func_ptr = ctypes.CFUNCTYPE(GSL_FN_DOUBLE_ARG1_TYPE, GSL_FN_DOUBLE_ARG1_TYPE, ctypes.c_void_p)(func_wrapper)
    function = gsl_function(func_ptr, None)
    w = gsl.gsl_integration_romberg_alloc(n)
    result = ctypes.c_double()
    abserr = ctypes.c_double()
    status = gsl.gsl_integration_romberg(ctypes.byref(function), a, b, epsabs, epsrel, n, 10, w, ctypes.byref(result), ctypes.byref(abserr))
    if status != 0:
        raise Exception("GSL integration failed")
    gsl.gsl_integration_romberg_free(w)
    return result.value, int(function.params)

