        raise ValueError("nx must be a positive integer")
    if not isinstance(ny, int) or ny <= 0:
        raise ValueError("ny must be a positive integer")
    if not all(isinstance(x, (int, float)) for x in xrange):
        raise ValueError("xrange must be a list of doubles")
    if not all(isinstance(y, (int, float)) for y in yrange):
        raise ValueError("yrange must be a list of doubles")
    if not all(xrange[i] < xrange[i+1] for i in range(len(xrange)-1)):
        raise ValueError("xrange must be in increasing order")
    if not all(yrange[i] < yrange[i+1] for i in range(len(yrange)-1)):
        raise ValueError("yrange must be in increasing order")

    x_range_c = (ctypes.c_double * len(xrange))(*xrange)
    y_range_c = (ctypes.c_double * len(yrange))(*yrange)

    result = gsl.gsl_histogram2d_calloc_range(nx, ny, x_range_c, y_range_c)
    if not result:
        raise RuntimeError("Failed to create histogram2d")

