gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GslRstatQuantileWorkspace:
    def __init__(self):
        self.workspace = gsl.gsl_rstat_quantile_alloc()

    def reset(self):
        gsl.gsl_rstat_quantile_reset(self.workspace)

    def add(self, value):
        gsl.gsl_rstat_quantile_add(self.workspace, ctypes.c_double(value))

    def get(self, p):
        return gsl.gsl_rstat_quantile_get(self.workspace, ctypes.c_double(p))

    def free(self):
        gsl.gsl_rstat_quantile_free(self.workspace)

def compute_quantile(p, values):
    workspace = GslRstatQuantileWorkspace()
    for value in values:
        workspace.add(value)
    quantile = workspace.get(p)
    workspace.free()
    return quantile

def test_compute_quantile():
    assert abs(compute_quantile(0.5, [1.0, 2.0, 3.0]) - 2.0) < 1e-6
    assert abs(compute_quantile(0.25, [4.0, 5.0, 6.0, 7.0, 8.0]) - 5.0) < 1e-6
    try:
        compute_quantile(2.0, [1.0, 2.0, 3.0])
        assert False, "Expected ValueError"
    except ValueError as e:
        pass

if __name__ == '__main__':
    test_compute_quantile()

