import ctypes
from ctypes import c_double, c_uint, POINTER

def load_gsl_libraries():
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        return gsl
    except OSError as e:
        print(f"Error loading GSL libraries: {e}")
        raise

def call_negative_binomial_cdf(gsl, k, p, n):
    c_k = c_uint(k)
    c_p = c_double(p)
    c_n = c_double(n)
    P = gsl.gsl_cdf_negative_binomial_P(c_k, c_p, c_n)
    Q = gsl.gsl_cdf_negative_binomial_Q(c_k, c_p, c_n)
    return float(P), float(Q)

def main(k, p, n):
    if k < 0 or p <= 0 or p >= 1 or n <= 0:
        raise ValueError("Invalid input values")
    gsl = load_gsl_libraries()
    P, Q = call_negative_binomial_cdf(gsl, k, p, n)
    return {"P": P, "Q": Q}

