# Define argument and return types for the C functions
def define_function(name, arg_types):
    func = gsl.__getattr__(name)
    func.argtypes = [ctypes.c_uint] + [ctypes.c_double]*2
    func.restype = ctypes.c_double

# Wrap the GSL functions
gsl_cdf_negative_binomial_P = define_function('gsl_cdf_negative_binomial_P', ['k', 'p', 'n'])
gsl_cdf_negative_binomial_Q = define_function('gsl_cdf_negative_binomial_Q', ['k', 'p', 'n'])

# Function to call the GSL functions from Python
def negative_binomial_cdf(k, p, n):
    return gsl_cdf_negative_binomial_P(k, p, n), gsl_cdf_negative_binomial_Q(k, p, n)

