    assert abs(negative_binomial_cdf(0, 0.5, 1)[0] - 0.5) < 1e-6
    assert abs(negative_binomial_cdf(1, 0.5, 1)[0] - 0.75) < 1e-6
    assert abs(negative_binomial_cdf(2, 0.5, 1)[0] - 0.875) < 1e-6
